using System.Net; 
using System.Net.Http.Headers; 
using System.Text; 
using System.Text.Json; 
using Microsoft.AspNetCore.Http; 
using RaceDay.MVC.Models; 
namespace RaceDay.MVC.Services; 
public class RaceDayApiClient { 
private readonly HttpClient _http; 
private readonly IHttpContextAccessor _ctx; 
private static readonly JsonSerializerOptions Opts = new() { PropertyNameCaseInsensitive = true }; 
public RaceDayApiClient(IHttpClientFactory factory, IHttpContextAccessor ctx) { _http = factory.CreateClient("RaceDayApi"); _ctx = ctx; } 
private void AttachAuthHeaders() { var s = _ctx.HttpContext?.Session; var uid = s?.GetInt32("UserId"); var role = s?.GetString("Role"); _http.DefaultRequestHeaders.Remove("X-User-Id"); _http.DefaultRequestHeaders.Remove("X-User-Role"); if (uid.HasValue) _http.DefaultRequestHeaders.Add("X-User-Id", uid.Value.ToString()); if (!string.IsNullOrEmpty(role)) _http.DefaultRequestHeaders.Add("X-User-Role", role); } 
public async Task<(bool Ok, AuthResponseDto? User, string? Error)> RegisterAsync(RegisterViewModel m) { var r = await _http.PostAsync("api/auth/register", new StringContent(JsonSerializer.Serialize(m), Encoding.UTF8, "application/json")); var b = await r.Content.ReadAsStringAsync(); return r.IsSuccessStatusCode ? (true, JsonSerializer.Deserialize<AuthResponseDto>(b, Opts), null) : (false, null, string.IsNullOrWhiteSpace(b) ? "Registration failed." : b); } 
public async Task<(bool Ok, AuthResponseDto? User, string? Error)> LoginAsync(LoginViewModel m) { var r = await _http.PostAsync("api/auth/login", new StringContent(JsonSerializer.Serialize(m), Encoding.UTF8, "application/json")); var b = await r.Content.ReadAsStringAsync(); return r.IsSuccessStatusCode ? (true, JsonSerializer.Deserialize<AuthResponseDto>(b, Opts), null) : (false, null, "Invalid email or password."); } 
public async Task LogoutAsync() { AttachAuthHeaders(); await _http.PostAsync("api/auth/logout", null); } 
public async Task<List<EventDto>> GetEventsAsync() { try { var r = await _http.GetAsync("api/events"); return r.IsSuccessStatusCode ? (JsonSerializer.Deserialize<List<EventDto>>(await r.Content.ReadAsStringAsync(), Opts) ?? new()) : new(); } catch { return new(); } } 
public async Task<EventDto?> GetEventByIdAsync(int id) { var r = await _http.GetAsync($"api/events/{id}"); return r.IsSuccessStatusCode ? JsonSerializer.Deserialize<EventDto>(await r.Content.ReadAsStringAsync(), Opts) : null; } 
public async Task<(bool Ok, EventDto? Created)> CreateEventAsync(EventFormViewModel m) { AttachAuthHeaders(); var r = await _http.PostAsync("api/events", new StringContent(JsonSerializer.Serialize(new { m.Name, m.Description, m.EventDate, m.Location, m.EventType, m.BannerImageUrl }), Encoding.UTF8, "application/json")); return r.IsSuccessStatusCode ? (true, JsonSerializer.Deserialize<EventDto>(await r.Content.ReadAsStringAsync(), Opts)) : (false, null); } 
public async Task<bool> UpdateEventAsync(int id, EventFormViewModel m) { AttachAuthHeaders(); return (await _http.PutAsync($"api/events/{id}", new StringContent(JsonSerializer.Serialize(new { m.Name, m.Description, m.EventDate, m.Location, m.EventType, m.BannerImageUrl }), Encoding.UTF8, "application/json"))).IsSuccessStatusCode; } 
public async Task<bool> DeleteEventAsync(int id) { AttachAuthHeaders(); return (await _http.DeleteAsync($"api/events/{id}")).IsSuccessStatusCode; } 
public async Task<string?> UploadEventBannerAsync(int eventId, IFormFile file) { AttachAuthHeaders(); using var form = new MultipartFormDataContent(); await using var s = file.OpenReadStream(); var sc = new StreamContent(s); sc.Headers.ContentType = new MediaTypeHeaderValue(file.ContentType); form.Add(sc, "file", file.FileName); var r = await _http.PostAsync($"api/events/{eventId}/upload-banner", form); if (!r.IsSuccessStatusCode) return null; using var d = JsonDocument.Parse(await r.Content.ReadAsStringAsync()); return d.RootElement.TryGetProperty("bannerImageUrl", out var p) ? p.GetString() : null; } 
public async Task<bool> AddCategoryAsync(CategoryFormViewModel m) { AttachAuthHeaders(); return (await _http.PostAsync($"api/events/{m.EventId}/categories", new StringContent(JsonSerializer.Serialize(new { m.CategoryName, m.Description, m.DistanceKm, m.Fee }), Encoding.UTF8, "application/json"))).IsSuccessStatusCode; } 
public async Task<(bool Ok, string? Error)> EnrolAsync(int eventId, int categoryId) { AttachAuthHeaders(); var r = await _http.PostAsync("api/enrolments", new StringContent(JsonSerializer.Serialize(new { eventId, categoryId }), Encoding.UTF8, "application/json")); return r.IsSuccessStatusCode ? (true, null) : (false, r.StatusCode == HttpStatusCode.Conflict ? "Already enrolled." : "Could not enrol."); } 
public async Task<List<EnrolmentDto>> GetMyEnrolmentsAsync() { AttachAuthHeaders(); var r = await _http.GetAsync("api/enrolments/my-enrolments"); return r.IsSuccessStatusCode ? (JsonSerializer.Deserialize<List<EnrolmentDto>>(await r.Content.ReadAsStringAsync(), Opts) ?? new()) : new(); } 
public async Task<List<EnrolmentDto>> GetEventEnrolmentsAsync(int eventId) { AttachAuthHeaders(); var r = await _http.GetAsync($"api/events/{eventId}/enrolments"); return r.IsSuccessStatusCode ? (JsonSerializer.Deserialize<List<EnrolmentDto>>(await r.Content.ReadAsStringAsync(), Opts) ?? new()) : new(); } 
public async Task<bool> SubmitResultAsync(ResultFormViewModel m) { AttachAuthHeaders(); return (await _http.PostAsync("api/results", new StringContent(JsonSerializer.Serialize(new { m.EnrolmentId, FinishTime = TimeSpan.Parse(m.FinishTime), m.OverallPosition, m.CategoryPosition }), Encoding.UTF8, "application/json"))).IsSuccessStatusCode; } 
public async Task<List<ResultDto>> GetMyResultsAsync() { AttachAuthHeaders(); var r = await _http.GetAsync("api/results/my-results"); return r.IsSuccessStatusCode ? (JsonSerializer.Deserialize<List<ResultDto>>(await r.Content.ReadAsStringAsync(), Opts) ?? new()) : new(); } 
public async Task<ProfileViewModel?> GetProfileAsync() { AttachAuthHeaders(); var r = await _http.GetAsync("api/users/profile"); return r.IsSuccessStatusCode ? JsonSerializer.Deserialize<ProfileViewModel>(await r.Content.ReadAsStringAsync(), Opts) : null; } 
public async Task<bool> UpdateProfileAsync(ProfileViewModel m) { AttachAuthHeaders(); return (await _http.PutAsync("api/users/profile", new StringContent(JsonSerializer.Serialize(new { m.FullName, m.PhoneNumber, m.ProfilePictureUrl }), Encoding.UTF8, "application/json"))).IsSuccessStatusCode; } 
public async Task<string?> UploadAvatarAsync(IFormFile file) { AttachAuthHeaders(); using var form = new MultipartFormDataContent(); await using var s = file.OpenReadStream(); var sc = new StreamContent(s); sc.Headers.ContentType = new MediaTypeHeaderValue(file.ContentType); form.Add(sc, "file", file.FileName); var r = await _http.PostAsync("api/users/profile/upload-avatar", form); if (!r.IsSuccessStatusCode) return null; using var d = JsonDocument.Parse(await r.Content.ReadAsStringAsync()); return d.RootElement.TryGetProperty("profilePictureUrl", out var p) ? p.GetString() : null; } 
} 


